-- Migration 015: Quest-Brett. Täglich je eine einfache, mittlere und schwere Aufgabe aus Vorlagen, besetzt mit echten Bewohnern (Rollen {A} {B} {C}).
-- Die Folgen treffen die besetzten Figuren wirklich: Beziehung ("sym") und Erinnerung ("merkt"), die auch die KI-Gespräche kennen.
alter table public.quest_templates add column if not exists art text not null default 'haupt';
alter table public.quest_templates add column if not exists schwierigkeit int;
alter table public.quest_templates add column if not exists rollen jsonb not null default '{}';
alter table public.quest_templates add column if not exists kurz text;
alter table public.quest_runs add column if not exists rollen jsonb not null default '{}';
alter table public.quest_runs add column if not exists angebot_id bigint;

create table if not exists public.quest_offers (
  id bigint generated always as identity primary key,
  player_id uuid not null references public.profiles(id) on delete cascade,
  tag date not null, slot text not null check (slot in ('einfach','mittel','schwer','individuell')),
  template_id text references public.quest_templates(id), rollen jsonb not null default '{}', ziel text,
  status text not null default 'offen' check (status in ('offen','angenommen','erledigt','wird_geschrieben','fehlgeschlagen')),
  run_id bigint, created_at timestamptz not null default now(), unique (player_id, tag, slot)
);
alter table public.quest_offers enable row level security; revoke all on public.quest_offers from anon, authenticated;

-- Platzhalter: Held, Begleiter und Rollen
create or replace function public.q_ctx(p_run quest_runs, p_wenn jsonb default null) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare held text; names text[]; bb text; roles jsonb;
begin
  select character_name into held from profiles where id = p_run.player_id;
  select array_agg(n.name order by array_position(p_run.begleiter, n.id)) into names from npcs n where n.id = any(p_run.begleiter);
  if p_wenn ? 'begleiter_beruf' then
    select n.name into bb from npcs n where n.id = any(p_run.begleiter) and n.job in (select jsonb_array_elements_text(p_wenn->'begleiter_beruf')) order by array_position(p_run.begleiter, n.id) limit 1;
  end if;
  select coalesce(jsonb_object_agg(key, value->>'name'), '{}'::jsonb) into roles from jsonb_each(coalesce(p_run.rollen, '{}'::jsonb));
  return jsonb_build_object('held', coalesce(held, 'du'), 'b1', coalesce(names[1], ''), 'bb', coalesce(bb, names[1], ''),
    'mit', case when coalesce(array_length(names, 1), 0) = 0 then 'allein' when array_length(names, 1) = 1 then 'mit ' || names[1] else 'mit ' || names[1] || ' und ' || names[2] end) || roles;
end;
$$;
revoke execute on function public.q_ctx(quest_runs, jsonb) from public, anon, authenticated;

-- Folgen für Rollen-Figuren (wird von q_apply aufgerufen)
create or replace function public.q_apply_roles(p_run quest_runs, f jsonb) returns void language plpgsql security definer set search_path = public as $$
declare k text; v text; nid bigint; ctx jsonb := q_ctx(p_run);
begin
  if f ? 'sym' then for k, v in select * from jsonb_each_text(f->'sym') loop
    nid := (p_run.rollen->k->>'id')::bigint; continue when nid is null;
    insert into npc_relations (npc_id, player_id, sympathy, loyalty) values (nid, p_run.player_id, 0, 0) on conflict do nothing;
    update npc_relations set sympathy = greatest(-100, least(100, sympathy + v::int)), updated_at = now() where npc_id = nid and player_id = p_run.player_id;
  end loop; end if;
  if f ? 'merkt' then for k, v in select * from jsonb_each_text(f->'merkt') loop
    nid := (p_run.rollen->k->>'id')::bigint; continue when nid is null;
    insert into npc_memories (npc_id, player_id, kind, text, sympathy_delta) values (nid, p_run.player_id, 'gespraech', left(q_fill(v, ctx), 300), coalesce((f->'sym'->>k)::int, 0));
  end loop; end if;
end;
$$;
revoke execute on function public.q_apply_roles(quest_runs, jsonb) from public, anon, authenticated;


-- q_apply: zusätzlich Rollen-Folgen
create or replace function public.q_apply(p_run_id bigint, f jsonb) returns text language plpgsql security definer set search_path = public as $$
declare r quest_runs; k text; v text; out text := ''; arm record; ctx jsonb; nid bigint; gst int; lt json; n int;
begin
  if f is null or f = '{}'::jsonb then return ''; end if;
  select * into r from quest_runs where id = p_run_id for update; ctx := q_ctx(r);
  perform q_apply_roles(r, f);
  if f ? 'flag' then update quest_runs set flags = flags || (select jsonb_object_agg(x, true) from jsonb_array_elements_text(f->'flag') x) where id = r.id; end if;
  if f ? 'item_plus' then for k, v in select * from jsonb_each_text(f->'item_plus') loop
    insert into player_items (player_id, item_id, menge) values (r.player_id, k, v::int) on conflict (player_id, item_id) do update set menge = player_items.menge + excluded.menge;
    out := out || ' Erhalten: ' || (select name from items where id = k) || case when v::int > 1 then ' ×' || v else '' end || '.'; end loop; end if;
  if f ? 'item_minus' then for k, v in select * from jsonb_each_text(f->'item_minus') loop update player_items set menge = greatest(0, menge - v::int) where player_id = r.player_id and item_id = k; end loop; end if;
  if f ? 'holz' then update villages set wood_stock = greatest(0, village_wood(villages) + (f->>'holz')::numeric), stock_updated_at = now() where owner_id = r.player_id; out := out || ' Holz ' || (f->>'holz') || '.'; end if;
  if (f ? 'begleiter_sym' or f ? 'begleiter_loy') and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    foreach nid in array r.begleiter loop
      insert into npc_relations (npc_id, player_id, sympathy, loyalty) values (nid, r.player_id, 0, 0) on conflict do nothing;
      update npc_relations set sympathy = greatest(-100, least(100, sympathy + coalesce((f->>'begleiter_sym')::int, 0))), loyalty = greatest(0, least(100, loyalty + coalesce((f->>'begleiter_loy')::int, 0))), updated_at = now() where npc_id = nid and player_id = r.player_id;
    end loop; end if;
  if f ? 'notiz' and coalesce(array_length(r.begleiter, 1), 0) > 0 then
    insert into player_notes (player_id, npc_id, kind, text) values (r.player_id, r.begleiter[1], 'begegnung', left(q_fill(f->>'notiz', ctx), 500));
    insert into npc_memories (npc_id, player_id, kind, text, sympathy_delta) values (r.begleiter[1], r.player_id, 'gespraech', 'Wir haben zusammen ein Abenteuer erlebt. ' || q_fill(f->>'notiz', ctx), 0);
  end if;
  if f ? 'chronik' then insert into chronicle (player_id, key, text) values (r.player_id, f->'chronik'->>0, q_fill(f->'chronik'->>1, ctx)) on conflict do nothing; end if;
  if f ? 'journal' then insert into player_journal (player_id, kind, key, title, text) values (r.player_id, 'auftrag', f->'journal'->>0, f->'journal'->>1, f->'journal'->>2) on conflict do nothing; out := out || ' Tagebuch: ' || (f->'journal'->>1) || '.'; end if;
  if f ? 'begleiter_ab' and coalesce(array_length(r.begleiter, 1), 0) > 0 then update quest_runs set begleiter = begleiter[2:] where id = r.id; end if;
  if f ? 'gefahr' then
    gst := case when jsonb_typeof(f->'gefahr') = 'number' then (f->>'gefahr')::int else 1 end;
    select e.src, e.ref, e.schutz, e.unverwuestlich, coalesce(g.name, i.name) as name into arm
      from p_equipment(r.player_id) e left join player_gear g on e.src = 'gear' and g.id::text = e.ref left join items i on e.src = 'item' and i.id = e.ref
      where e.art = 'ruestung' and e.schutz > 0 order by e.schutz desc limit 1;
    if arm.name is not null and arm.schutz >= gst then
      out := out || ' Deine Rüstung (' || arm.name || ') fängt das Schlimmste ab.';
      if arm.src = 'gear' and not arm.unverwuestlich then
        update player_gear set zustand = greatest(0, zustand - 20) where id = arm.ref::bigint returning zustand into n;
        if n = 0 then out := out || ' Es ist jetzt beschädigt und schützt nicht mehr, bis es repariert wird.'; end if;
      end if;
    else
      update profiles set zustand = 'verletzt', zustand_bis = now() + interval '6 hours' where id = r.player_id;
      out := out || case when arm.name is not null then ' Selbst deine Rüstung (' || arm.name || ') hilft hier nicht.' else '' end || ' Du bist verletzt (Proben −2 für einige Stunden).';
    end if;
  end if;
  if f ? 'beute' and random() < coalesce((f->'beute'->>'chance')::numeric, 1) then
    lt := loot_roll(r.player_id, coalesce((f->'beute'->>'stufe')::int, 1), f->'beute'->>'art', (select titel from quest_templates where id = r.quest_id));
    out := out || ' Gefunden: ' || (lt->>'name') || ' (' || (lt->>'stufe') || ').';
    update quest_runs set letztes = coalesce(letztes, '{}'::jsonb) || jsonb_build_object('beute', lt) where id = r.id;
  end if;
  return trim(out);
end;
$$;

-- Wahl treffen: Glücksbringer (einmal neu würfeln) und "erster Versuch sicher"

-- Szene betreten: Ende schließt auch das Angebot ab
create or replace function public.q_enter(p_run bigint, p_szene text) returns text language plpgsql security definer set search_path = public as $$
declare r quest_runs; sz jsonb; extra text := '';
begin
  select * into r from quest_runs where id = p_run; sz := (select def->'szenen'->p_szene from quest_templates where id = r.quest_id);
  if sz is null then raise exception 'Szene fehlt: %', p_szene; end if;
  update quest_runs set szene = p_szene, updated_at = now(), warte_bis = case when sz ? 'reise' then now() + make_interval(secs => (sz->'reise'->>'minuten')::numeric * 60) else null end where id = p_run;
  if coalesce((sz->>'ende')::boolean, false) then
    extra := q_apply(p_run, sz->'folgen'); update quest_runs set status = 'fertig' where id = p_run;
    update quest_offers set status = 'erledigt' where run_id = p_run;
  end if;
  return extra;
end;
$$;
revoke execute on function public.q_enter(bigint, text) from public, anon, authenticated;

-- Rollen mit Bewohnern des eigenen Dorfes besetzen
create or replace function public.q_cast(p_uid uuid, p_rollen jsonb) returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare v villages; keys text[]; picks record; res jsonb := '{}'::jsonb; i int := 0;
begin
  select * into v from villages where owner_id = p_uid;
  select array_agg(k order by k) into keys from jsonb_object_keys(coalesce(p_rollen, '{}'::jsonb)) k;
  if keys is null then return '{}'::jsonb; end if;
  for picks in select n.id, n.name, n.job from npcs n where n.village_id = v.id order by random() limit array_length(keys, 1) loop
    i := i + 1; res := res || jsonb_build_object(keys[i], jsonb_build_object('id', picks.id, 'name', picks.name, 'beruf', picks.job));
  end loop;
  if i < array_length(keys, 1) then return null; end if;
  return res;
end;
$$;
revoke execute on function public.q_cast(uuid, jsonb) from public, anon, authenticated;

-- Das Brett von heute (wird bei Bedarf angelegt)
create or replace function public.quest_board() returns json language plpgsql security definer set search_path = public as $$
declare d date := berlin_day(); sl text; st int; t quest_templates; rol jsonb;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  foreach sl in array array['einfach','mittel','schwer'] loop
    continue when exists (select 1 from quest_offers where player_id = auth.uid() and tag = d and slot = sl);
    st := case sl when 'einfach' then 1 when 'mittel' then 2 else 3 end;
    for t in select q.* from quest_templates q where q.art = 'brett' and q.schwierigkeit = st
      order by (select count(*) from quest_offers o where o.player_id = auth.uid() and o.template_id = q.id and o.tag > d - 7), random() loop
      rol := q_cast(auth.uid(), t.rollen);
      if rol is not null then insert into quest_offers (player_id, tag, slot, template_id, rollen) values (auth.uid(), d, sl, t.id, rol) on conflict do nothing; exit; end if;
    end loop;
  end loop;
  return json_build_object('tag', d, 'neu_ab', berlin_midnight(),
    'angebote', (select coalesce(json_agg(json_build_object('id', o.id, 'slot', o.slot, 'status', o.status, 'run', o.run_id, 'ziel', o.ziel,
        'titel', coalesce(tp.titel, 'Eigenes Abenteuer'), 'schwierigkeit', tp.schwierigkeit,
        'kurz', q_fill(coalesce(tp.kurz, o.ziel, ''), (select coalesce(jsonb_object_agg(key, value->>'name'), '{}'::jsonb) from jsonb_each(o.rollen))),
        'rollen', (select coalesce(json_agg(json_build_object('rolle', tp.rollen->>key, 'id', (value->>'id')::bigint, 'name', value->>'name', 'beruf', value->>'beruf')), '[]'::json) from jsonb_each(o.rollen)))
      order by array_position(array['einfach','mittel','schwer','individuell'], o.slot)), '[]'::json)
      from quest_offers o left join quest_templates tp on tp.id = o.template_id where o.player_id = auth.uid() and o.tag = d)
  );
end;
$$;
revoke execute on function public.quest_board() from public, anon; grant execute on function public.quest_board() to authenticated;

-- Ein Angebot annehmen
create or replace function public.quest_take(p_angebot bigint, p_begleiter bigint[]) returns json language plpgsql security definer set search_path = public as $$
declare o quest_offers; t quest_templates; v villages; rid bigint; nein text;
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet'; end if;
  perform ensure_starter_items(auth.uid());
  select * into o from quest_offers where id = p_angebot and player_id = auth.uid() for update;
  if not found or o.status <> 'offen' then raise exception 'Dieses Angebot gibt es nicht mehr'; end if;
  if exists (select 1 from quest_runs where player_id = auth.uid() and status = 'laeuft') then raise exception 'Du bist schon unterwegs'; end if;
  select * into t from quest_templates where id = o.template_id;
  select * into v from villages where owner_id = auth.uid();
  p_begleiter := coalesce(p_begleiter, '{}');
  if array_length(p_begleiter, 1) > 2 then raise exception 'Höchstens zwei Begleiter'; end if;
  if exists (select 1 from unnest(p_begleiter) b left join npcs n on n.id = b where n.id is null or n.village_id is distinct from v.id) then raise exception 'Begleiter müssen in deinem Dorf leben'; end if;
  if exists (select 1 from unnest(p_begleiter) b join jsonb_each(o.rollen) r on (r.value->>'id')::bigint = b) then return json_build_object('ok', false, 'grund', 'Wer in der Geschichte selbst eine Rolle spielt, kann nicht als Begleiter mit.'); end if;
  select string_agg(n.name, ', ') into nein from npcs n left join npc_relations r on r.npc_id = n.id and r.player_id = auth.uid() where n.id = any(p_begleiter) and coalesce(r.sympathy, 0) < 0;
  if nein is not null then return json_build_object('ok', false, 'grund', 'Nicht bereit, mit dir zu gehen: ' || nein); end if;
  insert into quest_runs (player_id, quest_id, szene, begleiter, rollen, angebot_id) values (auth.uid(), t.id, t.def->>'start', p_begleiter, o.rollen, o.id) returning id into rid;
  update quest_offers set status = 'angenommen', run_id = rid where id = o.id;
  return json_build_object('ok', true, 'view', quest_view(rid));
end;
$$;
revoke execute on function public.quest_take(bigint, bigint[]) from public, anon; grant execute on function public.quest_take(bigint, bigint[]) to authenticated;

-- Abbrechen gibt ein Brett-Angebot wieder frei
create or replace function public.quest_abort(p_run bigint) returns json language plpgsql security definer set search_path = public as $$
begin
  update quest_runs set status = 'abgebrochen', updated_at = now() where id = p_run and player_id = auth.uid() and status = 'laeuft';
  update quest_offers set status = 'offen', run_id = null where run_id = p_run and player_id = auth.uid() and slot <> 'individuell';
  return json_build_object('ok', true);
end;
$$;
revoke execute on function public.quest_abort(bigint) from public, anon; grant execute on function public.quest_abort(bigint) to authenticated;

-- Die ersten 6 Vorlagen (quests/brett.py)
insert into public.quest_templates (id, titel, beschreibung, kurz, art, schwierigkeit, rollen, def)
select e->>'id', e->>'titel', e->>'kurz', e->>'kurz', 'brett', (e->>'schwierigkeit')::int, e->'rollen', e->'def' from jsonb_array_elements($q$[{"id":"b_vorrat","titel":"Der verschwundene Vorrat","kurz":"{A} vermisst einen Sack Saatgut aus dem Vorratsschuppen. Jemand im Dorf muss ihn genommen haben.","schwierigkeit":1,"rollen":{"A":"Bestohlene Person","B":"Verdächtige Person","C":"Zeuge"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} steht vor dem offenen Schuppen, die Hände in die Hüften gestemmt. „Ein ganzer Sack Saatgut. Weg. Ohne den wird mein Feld im Frühjahr kahl bleiben.“","optionen":[{"text":"„Ich finde heraus, wer das war.“","weiter":"spuren"},{"text":"„Beruhig dich erst mal. Wir finden ihn.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":10},"erfolg":{"text":"{A} atmet durch. „Du hast recht. Ich hab mich da reingesteigert.“","folgen":{"sym":{"A":2}},"weiter":"spuren"},"misserfolg":{"text":"„Beruhigen? Das ist mein Winter, der da fehlt!“","weiter":"spuren"}}]},"spuren":{"ort":"dorf","text":"Im Staub vor dem Schuppen sind Spuren, und an der Tür hängt ein Faden grober, brauner Wolle.","optionen":[{"text":"Den Spuren folgen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":11},"erfolg":{"text":"Die Spuren führen zum Haus von {B} – und dort, halb unter Stroh versteckt, liegt der Sack.","folgen":{"flag":["beweis"]},"weiter":"entdeckt"},"misserfolg":{"text":"Die Spuren verlieren sich zwischen den Häusern.","weiter":"zeuge"}},{"text":"Herumfragen, wer etwas gesehen hat","weiter":"zeuge"}]},"zeuge":{"ort":"dorf","text":"{C} kratzt sich am Kinn. „Gestern Abend? Da hab ich {B} mit einem Sack über der Schulter gesehen. Hab mir nichts dabei gedacht.“","optionen":[{"text":"Zu {B} gehen","weiter":"entdeckt","folgen":{"merkt":{"C":"Ich habe {held} erzählt, was ich gesehen habe. Hoffentlich war das richtig."}}}]},"entdeckt":{"ort":"dorf","text":"{B} sieht dich kommen und wird blass. „Ich … meine Kinder hatten Hunger. Ich wollte es zurückgeben, sobald ich kann. Bitte sag es nicht {A}.“","optionen":[{"text":"Lügt {B}?","tag":"[Menschenkenntnis]","wenn":{"nicht_flag":"geprueft"},"probe":{"id":"menschenkenntnis","dc":11},"erfolg":{"text":"Die Angst ist echt. In der Küche steht ein leerer Topf.","folgen":{"flag":["geprueft","wahrheit"]},"weiter":"entdeckt"},"misserfolg":{"text":"Du kannst es nicht sagen.","folgen":{"flag":["geprueft"]},"weiter":"entdeckt"}},{"text":"Den Sack zurückbringen und {A} die Wahrheit sagen","weiter":"ende_wahrheit","ergebnis":"{A} nimmt den Sack schweigend entgegen. Dann geht {A} hinüber zu {B}. Was die beiden reden, hörst du nicht.","folgen":{"sym":{"A":4,"B":-4},"merkt":{"A":"{held} hat mein Saatgut gefunden und mir die Wahrheit über {B} gesagt.","B":"{held} hat mich verraten, obwohl ich gefleht habe."},"chronik":["brett_vorrat_wahrheit","Ich habe herausgefunden, dass {B} das Saatgut von {A} genommen hat – und es offen gesagt."]}},{"text":"Den Sack heimlich zurücklegen und schweigen","weiter":"ende_still","ergebnis":"In der Nacht stellst du den Sack zurück in den Schuppen. {A} findet ihn am Morgen und hält es für ein Wunder.","folgen":{"sym":{"A":1,"B":6},"merkt":{"B":"{held} hat geschwiegen und mich gerettet. Das vergesse ich nicht."},"chronik":["brett_vorrat_still","Ich habe für {B} geschwiegen und das Saatgut heimlich zurückgebracht."]}},{"text":"„Wir gehen zusammen zu {A}. Du erklärst es selbst.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":12,"mod":{"wahrheit":-2}},"erfolg":{"text":"{B} nickt zitternd. Vor {A} bricht {B} in Tränen aus. {A} schweigt lange – dann bietet {A} an, das Saatgut zu teilen.","folgen":{"sym":{"A":4,"B":4},"merkt":{"A":"{held} hat dafür gesorgt, dass {B} ehrlich zu mir war.","B":"{held} hat mir geholfen, das Richtige zu tun."},"chronik":["brett_vorrat_versoehnt","{A} und {B} haben sich versöhnt – ich habe sie zusammengebracht."]},"weiter":"ende_gut"},"misserfolg":{"text":"{B} schüttelt den Kopf. „Das kann ich nicht.“ Du bringst den Sack allein zurück.","folgen":{"sym":{"A":2,"B":-2}},"weiter":"ende_wahrheit"}}]},"ende_wahrheit":{"ort":"dorf","ende":true,"text":"Das Saatgut ist zurück. Im Dorf wird man darüber reden.","folgen":{"beute":{"stufe":1,"chance":0.5}}},"ende_still":{"ort":"dorf","ende":true,"text":"Ein Geheimnis mehr, das du trägst.","folgen":{"beute":{"stufe":1,"chance":0.4}}},"ende_gut":{"ort":"dorf","ende":true,"text":"Manchmal ist ein Streit der Anfang von etwas Besserem.","folgen":{"beute":{"stufe":1,"chance":0.7}}}}}},{"id":"b_brief","titel":"Ein Brief für die Mühle","kurz":"{A} bittet dich, einen versiegelten Brief zur Mühle am Bach zu bringen. Persönlich, sagt {A}, und schnell.","schwierigkeit":1,"rollen":{"A":"Absender","B":"Empfänger"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} drückt dir einen gefalteten Brief mit einem Wachssiegel in die Hand. „Für {B}. Gib ihn niemand anderem. Und … lies ihn nicht.“","optionen":[{"text":"Losgehen","weiter":"weg"}]},"weg":{"ort":"wald","text":"Der Pfad zur Mühle folgt dem Bach. Das Wasser glitzert, irgendwo klopft ein Specht.","reise":{"minuten":1,"weiter":"zweifel","begegnung":{"chance":0.3,"szenen":["b_haendler","b_wanderer"]}}},"b_haendler":{"ort":"wald","text":"Ein Händler hockt am Wegrand und flickt seinen Karren. „Hilf mir kurz, Freund? Das Rad will nicht.“","optionen":[{"text":"Mit anpacken","tag":"[Anpacken]","probe":{"id":"anpacken","dc":10},"erfolg":{"text":"Das Rad sitzt. Der Händler drückt dir zum Dank etwas in die Hand.","folgen":{"beute":{"stufe":1,"chance":1}},"weiter":"zweifel"},"misserfolg":{"text":"Ihr flucht beide, aber am Ende hält es irgendwie.","weiter":"zweifel"}},{"text":"Keine Zeit, der Brief eilt","weiter":"zweifel"}]},"b_wanderer":{"ort":"wald","text":"Ein alter Mann sitzt auf einem Stein. „Zur Mühle? Grüß mir das Wasserrad. Wir sind zusammen alt geworden.“ Er lacht leise.","optionen":[{"text":"Ein Stück mit ihm reden","weiter":"zweifel","ergebnis":"Er erzählt von früher, als die Mühle noch drei Räder hatte."}]},"zweifel":{"ort":"wald","text":"Kurz vor der Mühle löst sich das Siegel ein wenig. Man könnte hineinschauen, ohne dass es jemand merkt.","optionen":[{"text":"Hineinschauen","tag":"[Flink]","probe":{"id":"flink","dc":11},"erfolg":{"text":"Du liest: „Ich habe es nie vergessen. Komm zum Fest. Bitte.“ Du klebst das Siegel sauber wieder zu.","folgen":{"flag":["gelesen"]},"weiter":"muehle"},"misserfolg":{"text":"Das Siegel bricht ganz. Jetzt sieht man, dass jemand den Brief geöffnet hat.","folgen":{"flag":["gelesen","siegel_kaputt"]},"weiter":"muehle"}},{"text":"Den Brief ungelesen lassen","weiter":"muehle","folgen":{"flag":["treu"]}}]},"muehle":{"ort":"dorf","text":"{B} wischt sich das Mehl von den Händen und nimmt den Brief. Als {B} den Absender erkennt, wird es still.","optionen":[{"text":"Abwarten","wenn":{"nicht_flag":"siegel_kaputt"},"weiter":"antwort"},{"text":"„Das Siegel war schon kaputt, als …“","tag":"[Überreden]","wenn":{"flag":"siegel_kaputt"},"probe":{"id":"ueberreden","dc":13},"erfolg":{"text":"{B} glaubt dir – oder will dir glauben.","weiter":"antwort"},"misserfolg":{"text":"{B} sieht dich lange an. „Du hast ihn gelesen.“","folgen":{"sym":{"B":-4,"A":-3},"merkt":{"B":"{held} hat meinen Brief gelesen. Neugieriges Volk."}},"weiter":"antwort"}},{"text":"Die Wahrheit sagen: „Ich habe hineingeschaut. Es tut mir leid.“","wenn":{"flag":"gelesen"},"weiter":"antwort","ergebnis":"{B} schnaubt – dann lächelt {B} schief. „Wenigstens ehrlich.“","folgen":{"sym":{"B":1}}}]},"antwort":{"ort":"dorf","text":"{B} schreibt ein paar Zeilen auf die Rückseite und faltet den Brief neu. „Bring ihn zurück. Und sag {A} … nein. Bring ihn einfach.“","optionen":[{"text":"Zurück zu {A}","weiter":"ende","folgen":{"sym":{"A":4,"B":2},"merkt":{"A":"{held} hat meinen Brief zu {B} gebracht – und eine Antwort mitgebracht.","B":"{held} hat mir einen Brief von {A} gebracht. Nach all den Jahren."},"chronik":["brett_brief","Ich habe einen Brief zwischen {A} und {B} getragen. Was darin stand, war wichtig."]}}]},"ende":{"ort":"dorf","ende":true,"text":"{A} liest die Antwort und dreht sich weg, damit du die Augen nicht siehst. „Danke“, sagt {A} leise.","folgen":{"beute":{"stufe":1,"chance":0.5}}}}}},{"id":"b_grenzstein","titel":"Streit um den Grenzstein","kurz":"{A} und {B} streiten, wem das Stück Land am alten Grenzstein gehört. Das Dorf erwartet, dass jemand entscheidet.","schwierigkeit":2,"rollen":{"A":"Streitpartei","B":"Streitpartei","C":"Älteste Stimme"},"def":{"start":"streit","szenen":{"streit":{"ort":"dorf","text":"Am Feldrand stehen sich {A} und {B} gegenüber. „Der Stein stand immer hier!“ – „Weil du ihn letzten Herbst versetzt hast!“ Ein paar Leute sehen zu.","optionen":[{"text":"Dazwischengehen und beide beruhigen","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":12},"erfolg":{"text":"Die Stimmen werden leiser. Beide sind bereit, dich anzuhören.","folgen":{"flag":["ruhig"]},"weiter":"pruefen"},"misserfolg":{"text":"„Halt dich raus!“, rufen beide gleichzeitig. Immerhin sind sie sich da einig.","weiter":"pruefen"}},{"text":"„Ich sehe mir den Stein an.“","weiter":"pruefen"}]},"pruefen":{"ort":"wald","text":"Der Grenzstein ist alt und bemoost. Am Boden daneben sieht man eine frische Kuhle, als hätte man ihn bewegt – oder als hätten Wildschweine gewühlt.","optionen":[{"text":"Den Boden genau untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":13},"erfolg":{"text":"Die Kuhle stammt von Schweinen. Aber unter dem Moos zeigt eine verwitterte Kerbe in Richtung von {B}s Feld.","folgen":{"flag":["kerbe"]},"weiter":"wissen"},"misserfolg":{"text":"Du wirst nicht schlau daraus.","weiter":"wissen"}},{"text":"Die alten Zeichen auf dem Stein deuten","tag":"[Altes Wissen]","probe":{"id":"altes_wissen","dc":12},"erfolg":{"text":"Das Zeichen ist ein altes Flurmal: Die Grenze verläuft entlang der Kerbe – und die zeigt zu {B}.","folgen":{"flag":["kerbe","gedeutet"]},"weiter":"wissen"},"misserfolg":{"text":"Die Zeichen sind zu verwittert.","weiter":"wissen"}},{"text":"{C} fragen, wie es früher war","weiter":"aelteste"}]},"aelteste":{"ort":"dorf","text":"{C} lehnt sich zurück. „Als ich jung war, hat der Stein weiter drüben gestanden. Aber das ist lange her, und das Gedächtnis ist ein Lügner.“","optionen":[{"text":"Zurück zum Feld","weiter":"wissen","folgen":{"flag":["erinnerung"]}}]},"wissen":{"ort":"dorf","text":"Alle warten auf dein Wort. {A} sieht dich hoffnungsvoll an, {B} mit verschränkten Armen.","optionen":[{"text":"Für {B} entscheiden: Die alte Kerbe zählt.","wenn":{"flag":"kerbe"},"weiter":"ende","ergebnis":"{B} nickt zufrieden. {A} schluckt – aber gegen das alte Zeichen kann niemand etwas sagen.","folgen":{"sym":{"B":5,"A":-1,"C":2},"merkt":{"B":"{held} hat gerecht entschieden – mit Beweis.","A":"{held} hat gegen mich entschieden. Aber mit Beweis."},"chronik":["brett_grenze_beweis","Ich habe den Grenzstreit zwischen {A} und {B} mit einem alten Flurmal entschieden."]}},{"text":"Für {A} entscheiden – {A} braucht das Land dringender.","weiter":"ende","ergebnis":"{A} atmet auf. {B} spuckt aus und geht.","folgen":{"sym":{"A":6,"B":-6},"merkt":{"A":"{held} hat zu mir gehalten.","B":"{held} hat mir mein Land genommen. Das merke ich mir."},"chronik":["brett_grenze_a","Im Grenzstreit habe ich mich auf die Seite von {A} gestellt."]}},{"text":"Teilen: Jeder bekommt die Hälfte, und beide pflügen gemeinsam.","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"ruhig":-2,"erinnerung":-1}},"erfolg":{"text":"Lange Stille. Dann streckt {A} die Hand aus. {B} schlägt ein – zögernd, aber ein.","folgen":{"sym":{"A":4,"B":4,"C":3},"merkt":{"A":"{held} hat einen Frieden gefunden, den ich nicht gesehen habe.","B":"{held} hat uns beide überredet. Klug."},"chronik":["brett_grenze_frieden","Ich habe den Grenzstreit zwischen {A} und {B} geschlichtet."]},"weiter":"ende"},"misserfolg":{"text":"„Teilen? Mit dem?“ Beide gehen im Zorn. Der Streit ist nicht vorbei.","folgen":{"sym":{"A":-2,"B":-2},"chronik":["brett_grenze_offen","Der Grenzstreit zwischen {A} und {B} schwelt weiter."]},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Stein steht, wo er steht. Ob die Wunden heilen, wird sich zeigen.","folgen":{"beute":{"stufe":2,"chance":0.6}}}}}},{"id":"b_fieber","titel":"Fieber im Dorf","kurz":"Das Kind von {A} glüht vor Fieber. Die Kräuter im Dorf sind aufgebraucht – im Wald wächst Weidenröschen, aber dort streunen Wölfe.","schwierigkeit":2,"rollen":{"A":"Elternteil","B":"Kundige Person"},"def":{"start":"krank","szenen":{"krank":{"ort":"dorf","text":"Im Halbdunkel der Hütte liegt ein Kind unter Fellen, das Gesicht nass vom Schweiß. {A} hält seine Hand. „{B} sagt, nur frisches Weidenröschen hilft noch.“","optionen":[{"text":"Das Kind selbst untersuchen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":12},"erfolg":{"text":"Du kühlst die Stirn mit nassen Tüchern und flößt Wasser ein. Das verschafft Zeit.","folgen":{"flag":["zeit"]},"weiter":"aufbruch"},"misserfolg":{"text":"Du weißt nicht genug darüber. Es bleibt nur der Wald.","weiter":"aufbruch"}},{"text":"„Ich hole die Kräuter.“","weiter":"aufbruch"}]},"aufbruch":{"ort":"wald","text":"Der Wald ist still und kalt. Irgendwo in den Senken soll das Weidenröschen wachsen.","reise":{"minuten":2,"weiter":"senke","begegnung":{"chance":0.5,"szenen":["woelfe"]}}},"woelfe":{"ort":"wald","gefahr":true,"text":"Zwei Wölfe treten aus dem Unterholz. Mager, hungrig, wachsam.","optionen":[{"text":"Warnschuss","tag":"[Bogen]","wenn":{"item":"bogen"},"probe":{"id":"flink","dc":10},"erfolg":{"text":"Der Pfeil fährt zwischen ihnen in den Boden. Sie fliehen.","weiter":"senke"},"misserfolg":{"text":"Daneben – einer springt dich an, bevor beide abhauen.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"Groß machen und brüllen","tag":"[Einschüchtern]","probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Sie weichen zurück.","weiter":"senke"},"misserfolg":{"text":"Ein Biss, dann sind sie fort.","folgen":{"gefahr":1},"weiter":"senke"}},{"text":"{bb} kennt sich mit Tieren aus","tag":"[{bb}]","wenn":{"begleiter_beruf":["Jäger","Jägerin","Hirte","Falknerin"]},"weiter":"senke","ergebnis":"{bb} führt euch in weitem Bogen gegen den Wind vorbei.","folgen":{"begleiter_sym":2}}]},"senke":{"ort":"wald","text":"In einer feuchten Senke leuchten violette Blüten. Daneben: ein zweiter Strauch – größer, aber du bist nicht sicher, ob er nicht giftig ist.","optionen":[{"text":"Die Pflanzen genau bestimmen","tag":"[Heilkunde]","probe":{"id":"heilkunde","dc":11},"erfolg":{"text":"Der kleine ist das Weidenröschen, der große ist Fingerhut – giftig. Gut, dass du hingesehen hast.","folgen":{"flag":["richtig"]},"weiter":"rueckweg"},"misserfolg":{"text":"Du nimmst von beiden. Sicher ist sicher.","folgen":{"flag":["beides"]},"weiter":"rueckweg"}},{"text":"Einfach den großen Strauch nehmen – mehr hilft mehr","weiter":"rueckweg","folgen":{"flag":["falsch"]}}]},"rueckweg":{"ort":"wald","text":"Mit vollen Taschen eilst du zurück.","reise":{"minuten":1,"weiter":"heilen"}},"heilen":{"ort":"dorf","text":"{B} nimmt dir die Pflanzen ab und betrachtet sie genau.","optionen":[{"text":"Abwarten","wenn":{"flag":"richtig"},"weiter":"ende_gut","ergebnis":"„Genau das“, murmelt {B} und braut einen Sud. In der Nacht sinkt das Fieber.","folgen":{"sym":{"A":8,"B":3},"merkt":{"A":"{held} hat meinem Kind das Leben gerettet.","B":"{held} kennt sich mit Kräutern aus. Das hätte ich nicht gedacht."},"chronik":["brett_fieber_gerettet","Ich habe Weidenröschen für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"beides"},"weiter":"ende_gut","ergebnis":"{B} sortiert den Fingerhut aus und schüttelt den Kopf. „Gut, dass du mir beides gebracht hast.“ Das Fieber sinkt bis zum Morgen.","folgen":{"sym":{"A":6,"B":2},"merkt":{"A":"{held} hat Kräuter für mein Kind geholt."},"chronik":["brett_fieber_gerettet","Ich habe Kräuter für das kranke Kind von {A} geholt. Es ist wieder gesund."]}},{"text":"Abwarten","wenn":{"flag":"falsch"},"weiter":"ende_knapp","ergebnis":"{B} wird bleich. „Das ist Fingerhut! Hätte ich das gekocht …“ {B} schickt dich noch einmal los, diesmal mit genauer Beschreibung. Erst im Morgengrauen sinkt das Fieber.","folgen":{"sym":{"A":2,"B":-2},"merkt":{"B":"{held} hätte beinahe Gift gebracht. Gut, dass ich nachgesehen habe."},"chronik":["brett_fieber_knapp","Ich hätte dem kranken Kind von {A} beinahe Gift gebracht. Es ging gerade noch gut."]}}]},"ende_gut":{"ort":"dorf","ende":true,"text":"Am nächsten Tag sitzt das Kind schon wieder am Feuer und fragt, wann du mal wieder Geschichten erzählst.","folgen":{"beute":{"stufe":2,"chance":0.7}}},"ende_knapp":{"ort":"dorf","ende":true,"text":"Das Kind wird gesund. Aber du wirst diese Nacht nicht so schnell vergessen.","folgen":{"beute":{"stufe":1,"chance":0.5}}}}}},{"id":"b_hohlweg","titel":"Die Räuber vom Hohlweg","kurz":"Am Hohlweg werden Reisende überfallen. {A} hat dort Waren verloren und will, dass jemand die Räuber vertreibt – so oder so.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Wer die Gegend kennt"},"def":{"start":"auftrag","szenen":{"auftrag":{"ort":"dorf","text":"{A} zeigt dir einen zerrissenen Beutel. „Drei Männer, vermummt. Sie haben alles genommen. Wenn das so weitergeht, kommt kein Händler mehr zu uns.“ {B} fügt leise hinzu: „Ich kenne einen Pfad oberhalb des Hohlwegs.“","optionen":[{"text":"Den oberen Pfad nehmen und die Räuber beobachten","weiter":"pfad"},{"text":"Offen den Hohlweg hinaufgehen – sollen sie nur kommen","weiter":"offen"}]},"pfad":{"ort":"wald","text":"Ihr klettert über Wurzeln und Geröll, bis ihr auf den Hohlweg hinabsehen könnt.","reise":{"minuten":2,"weiter":"lager"}},"offen":{"ort":"wald","text":"Der Hohlweg ist eng, die Böschungen hoch. Ein guter Ort für einen Hinterhalt.","reise":{"minuten":1,"weiter":"hinterhalt"}},"hinterhalt":{"ort":"wald","gefahr":true,"text":"Steine poltern. Drei Gestalten springen auf den Weg, Knüppel und ein rostiges Messer in den Händen. „Beutel her!“","optionen":[{"text":"Kämpfen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":14},"erfolg":{"text":"Du schlägst den ersten nieder, die anderen zögern. Einer lässt die Kapuze fallen – ein abgemagerter Junge.","folgen":{"flag":["gesiegt"]},"weiter":"entlarvt"},"misserfolg":{"text":"Ein Knüppel trifft dich hart. Aber dann rutscht einem die Kapuze herunter – ein Junge, kaum älter als fünfzehn.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"Die Waffe ziehen und drohen","tag":"[Einschüchtern]","wenn":{"item_eines":["schwert","axt","dolch","saebel","speer"]},"probe":{"id":"einschuechtern","dc":12},"erfolg":{"text":"Stahl blitzt. Die drei weichen zurück, einer stolpert und verliert die Kapuze – ein Junge.","weiter":"entlarvt"},"misserfolg":{"text":"Sie greifen trotzdem an.","folgen":{"gefahr":2},"weiter":"entlarvt"}},{"text":"„Wartet. Warum tut ihr das?“","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"Du siehst die zitternden Hände, die eingefallenen Wangen. Das sind keine Räuber. Das sind Hungrige.","folgen":{"flag":["verstanden"]},"weiter":"entlarvt"},"misserfolg":{"text":"Die Antwort ist ein Knüppelhieb.","folgen":{"gefahr":2},"weiter":"entlarvt"}}]},"lager":{"ort":"wald","text":"Unter euch, in einer Felsnische: ein armseliges Lager. Drei Männer – nein, zwei Männer und ein Junge – teilen sich einen dürren Hasen. Neben ihnen liegen {A}s Waren, unberührt.","optionen":[{"text":"Lauschen","tag":"[Schleichen]","probe":{"id":"flink","dc":12},"erfolg":{"text":"„Die Waren tauschen wir in Salzwacht gegen Korn. Dann gehen wir heim nach Erzklamm. Seit die Mine eingestürzt ist …“","folgen":{"flag":["verstanden","unentdeckt"]},"weiter":"entscheidung"},"misserfolg":{"text":"Ein Stein löst sich. Die drei springen auf.","weiter":"hinterhalt"}},{"text":"Ein Seil spannen und eine Falle am Ausgang der Nische stellen","tag":"[Anpacken]","wenn":{"item":"seil"},"probe":{"id":"anpacken","dc":11},"erfolg":{"text":"Die Falle sitzt. Wenn sie fliehen wollen, gehen sie zu Boden.","folgen":{"flag":["falle"]},"weiter":"entscheidung"},"misserfolg":{"text":"Das Seil verheddert sich.","weiter":"entscheidung"}},{"text":"Hinuntersteigen und sie stellen","weiter":"entscheidung"}]},"entlarvt":{"ort":"wald","text":"Der Älteste hebt die Hände. „Wir sind aus Erzklamm. Die Mine ist eingestürzt, es gibt kein Brot mehr. Wir wollten niemandem wehtun.“","optionen":[{"text":"Weiter","weiter":"entscheidung"}]},"entscheidung":{"ort":"wald","text":"Die Räuber sind in deiner Hand. {A}s Waren liegen da. Was jetzt?","optionen":[{"text":"Die Waren nehmen und sie laufen lassen","weiter":"ende","ergebnis":"Sie verschwinden zwischen den Bäumen. Einer dreht sich noch einmal um und nickt dir zu.","folgen":{"sym":{"A":4},"merkt":{"A":"{held} hat meine Waren zurückgebracht. Die Räuber sind fort."},"chronik":["brett_hohlweg_frei","Ich habe die Räuber vom Hohlweg laufen lassen – hungrige Leute aus Erzklamm."]}},{"text":"Sie gefangen nehmen und ins Dorf bringen","tag":"[Anpacken]","probe":{"id":"anpacken","dc":12,"mod":{"falle":-4,"gesiegt":-2}},"erfolg":{"text":"Gefesselt führst du sie ins Dorf. {A} ist zufrieden. Was mit ihnen geschieht, entscheidet die Versammlung.","folgen":{"sym":{"A":6,"B":1},"merkt":{"A":"{held} hat die Räuber gefangen. Endlich Ruhe."},"chronik":["brett_hohlweg_gefangen","Ich habe die Räuber vom Hohlweg gefangen ins Dorf gebracht."]},"weiter":"ende"},"misserfolg":{"text":"Zwei entkommen, nur der Junge bleibt zurück. Er weint.","folgen":{"sym":{"A":3},"chronik":["brett_hohlweg_junge","Am Hohlweg habe ich einen jungen Räuber aus Erzklamm gefangen. Die anderen sind entkommen."]},"weiter":"ende"}},{"text":"„Kommt mit ins Dorf. Arbeit gegen Brot – das ist besser als der Hohlweg.“","tag":"[Überreden]","probe":{"id":"ueberreden","dc":14,"mod":{"verstanden":-3}},"erfolg":{"text":"Lange Stille. Dann nickt der Älteste. „Wenn ihr uns nehmt, arbeiten wir.“ {A} ist skeptisch, aber die Waren sind zurück.","folgen":{"sym":{"A":2,"B":4},"merkt":{"A":"{held} hat die Räuber ins Dorf geholt. Ich traue ihnen nicht. Aber meine Waren sind zurück.","B":"{held} hat aus Räubern Arbeiter gemacht. Mutig."},"chronik":["brett_hohlweg_arbeit","Ich habe den Räubern vom Hohlweg Arbeit im Dorf angeboten. Sie kamen mit."],"journal":["erzklamm_fluechtlinge","Leute aus Erzklamm","Drei Männer aus Erzklamm arbeiten jetzt im Dorf. In Erzklamm herrscht Hunger, seit die Mine eingestürzt ist."]},"weiter":"ende"},"misserfolg":{"text":"„Damit ihr uns dann aufknüpft? Nein.“ Sie lassen die Waren fallen und fliehen.","folgen":{"sym":{"A":3}},"weiter":"ende"}}]},"ende":{"ort":"dorf","ende":true,"text":"Der Hohlweg ist wieder frei. Doch Erzklamm hungert, und das wird nicht die letzte Geschichte sein.","folgen":{"beute":{"stufe":3,"chance":1}}}}}},{"id":"b_brand","titel":"Feuer in der Nacht","kurz":"Mitten in der Nacht brennt die Scheune von {A}. Jemand behauptet, {B} sei kurz vorher dort gewesen.","schwierigkeit":3,"rollen":{"A":"Geschädigte Person","B":"Beschuldigte Person","C":"Wer etwas gesehen hat"},"def":{"start":"feuer","szenen":{"feuer":{"ort":"dorf","gefahr":true,"text":"Rufe reißen dich aus dem Schlaf. Flammen schlagen aus dem Dach der Scheune von {A}. Drinnen brüllt das Vieh.","optionen":[{"text":"Hineinlaufen und das Vieh befreien","tag":"[Flink]","probe":{"id":"flink","dc":13},"erfolg":{"text":"Du reißt das Tor auf, die Tiere stürmen hinaus. Hinter dir kracht ein Balken.","folgen":{"flag":["vieh"],"sym":{"A":4}},"weiter":"loeschen"},"misserfolg":{"text":"Rauch, Hitze, ein brennender Balken streift dich. Aber die Tiere sind draußen.","folgen":{"flag":["vieh"],"sym":{"A":4},"gefahr":2},"weiter":"loeschen"}},{"text":"Eine Eimerkette organisieren","tag":"[Überreden]","probe":{"id":"ueberreden","dc":11},"erfolg":{"text":"Auf dein Kommando reihen sich alle auf. Eimer um Eimer fliegt ins Feuer.","folgen":{"flag":["kette"]},"weiter":"loeschen"},"misserfolg":{"text":"Alle laufen durcheinander.","weiter":"loeschen"}}]},"loeschen":{"ort":"dorf","text":"Im Morgengrauen ist das Feuer aus. Die Scheune ist eine schwarze Ruine. {C} zieht dich beiseite: „Ich hab {B} gestern Abend dort gesehen. Mit einer Laterne.“","optionen":[{"text":"Die Brandstelle untersuchen","tag":"[Spuren lesen]","probe":{"id":"spuren","dc":14},"erfolg":{"text":"Das Feuer begann nicht am Tor, wo {B} gestanden haben soll, sondern hinten, bei der Heuluke. Dort liegt eine umgekippte Öllampe – die von {A} selbst.","folgen":{"flag":["unfall"]},"weiter":"anklage"},"misserfolg":{"text":"Asche und Ruß. Nichts, was eindeutig wäre.","weiter":"anklage"}},{"text":"{C} genauer befragen","tag":"[Menschenkenntnis]","probe":{"id":"menschenkenntnis","dc":13},"erfolg":{"text":"{C} weicht deinem Blick aus. Zwischen {C} und {B} gibt es alten Streit – um ein Mädchen, vor Jahren.","folgen":{"flag":["groll"]},"weiter":"anklage"},"misserfolg":{"text":"{C} klingt sicher.","weiter":"anklage"}}]},"anklage":{"ort":"dorf","text":"Das halbe Dorf steht vor der Ruine. {A} zeigt auf {B}. „Warst du es?“ {B} schüttelt stumm den Kopf. Alle sehen dich an.","optionen":[{"text":"„Es war ein Unfall. Die Lampe von {A} lag an der Heuluke.“","wenn":{"flag":"unfall"},"weiter":"ende","ergebnis":"Ein Raunen. {A} wird rot und senkt den Kopf. {B} sieht dich an, als hättest du gerade ein Leben gerettet – und vielleicht hast du das.","folgen":{"sym":{"B":8,"A":1,"C":-3},"merkt":{"B":"{held} hat bewiesen, dass ich es nicht war. Ich stehe in dieser Schuld.","C":"{held} hat mich vor allen bloßgestellt."},"chronik":["brett_brand_unfall","Ich habe bewiesen, dass der Brand bei {A} ein Unfall war – und {B} vor einer falschen Anklage bewahrt."]}},{"text":"„{C} hat einen alten Groll gegen {B}. Ich glaube {C} nicht.“","wenn":{"flag":"groll"},"weiter":"ende","ergebnis":"{C} läuft rot an und geht. Der Verdacht gegen {B} bleibt im Raum – aber er wackelt.","folgen":{"sym":{"B":4,"C":-5},"merkt":{"C":"{held} hat mich vor allen einen Lügner genannt.","B":"{held} hat zu mir gehalten."},"chronik":["brett_brand_groll","Beim Brand bei {A} habe ich die Aussage von {C} angezweifelt."]}},{"text":"„Ich weiß es nicht. Aber ohne Beweis wird niemand verurteilt.“","tag":"[Beruhigen]","probe":{"id":"beruhigen","dc":13},"erfolg":{"text":"Die Menge murrt, aber sie zerstreut sich. Niemand wird heute bestraft.","folgen":{"sym":{"B":3}},"weiter":"ende"},"misserfolg":{"text":"„Wer soll es sonst gewesen sein?“ {B} muss das Dorf für eine Weile meiden.","folgen":{"sym":{"B":-2,"A":2},"chronik":["brett_brand_verdacht","Nach dem Brand bei {A} fällt ein Schatten auf {B}."]},"weiter":"ende"}},{"text":"{B} beschuldigen","weiter":"ende","ergebnis":"{B} sieht dich an, als hättest du zugeschlagen. Dann geht {B}, ohne ein Wort.","folgen":{"sym":{"A":4,"B":-10,"C":3},"merkt":{"B":"{held} hat mich verurteilt, ohne Beweis. Das verzeihe ich nicht.","A":"{held} hat mir geholfen, den Schuldigen zu finden."},"chronik":["brett_brand_schuld","Ich habe {B} für den Brand bei {A} verantwortlich gemacht."]}}]},"ende":{"ort":"dorf","ende":true,"text":"Die Scheune muss neu gebaut werden. Und was in dieser Nacht gesagt wurde, bleibt.","folgen":{"beute":{"stufe":3,"chance":0.9}}}}}}]$q$::jsonb) e
